window.VD=window.VD||{};window.VD["seat-cupra/tarraco-kn"]={"tarraco-kn-120-km-h-overtaking-alert":"<p><strong>Purpose: </strong>To activate or deactivate a message reminding you that you are exceeding the 120km/h speed limit.  </p>\n<p><strong>Procedure: </strong><br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.  </p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:  </strong></p>\n<p><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“17 – Instruments</strong>”.  </p>\n<p><strong>4</strong> – Click on<strong>“Coding – 07</strong>” then click on<strong>“Long Coding Wizard</strong>”.  </p>\n<p><strong>5</strong> – Select byte<strong>“0”</strong> <br/>Then check to enable or uncheck to disable the box in<strong>“6”</strong>:<strong>“Speed warning at 120 kph (75 mph) active</strong>”.  </p>","tarraco-kn-activate-auto-school-mode":"<p><strong>Purpose:</strong> Adds a driving-school mode view to the screen, displaying indicators, speed, etc. (also ideal for accompanied driving).  <br/><br/><br/><strong>Watch out! There are 3 lines of coding to do here. </strong> <br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“5F – Electr. information</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Vehicule function list CAN-Driving_school</strong>“.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“active</strong>” and confirm.<br/><br/><strong>Line 2:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“5F – Electr. information</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Vehicule menu operation-menu_display_driving_school</strong>“.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“active</strong>” and confirm.<br/><br/><strong>Line 3:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“5F – Electr. information</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Vehicule menu operation-menu_display_driving_school_over_threshold_high</strong>“.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“active</strong>” and confirm.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/discoverautoecole-4d14ae9a.webp\"/></figure>","tarraco-kn-activate-daytime-running-lights-drl-only-in-auto-position":"<p><strong>Purpose:</strong> Enables daytime running lights (DRL) only when the headlight control switch is in the “auto” position.  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – At the very top of this page, there is a drop-down menu.<br/>From this drop-down menu, select “<strong>Daytime running lights—Daytime running lights only in the AUTO position</strong>.”<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“active</strong>” and confirm.<br/></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/5Q0-937-084-Q_Module09_Adaptation_drl_auto_switch-c7669352.webp\"/></figure>","tarraco-kn-activate-intruder-alarm-with-horn":"<p><strong>Purpose:</strong> to activate an alarm with horn in the event of intrusion into the vehicle, and to lock the door if it is opened using the interior handles.  </p>\n<p><strong>Warning! There are 8 lines of coding to do here. </strong> </p>\n<p><em><strong>For vehicles without original alarm! </strong></em><br/><br/><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.</p>\n<p><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.</p>\n<p><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Additional functions – Signalhorn ohne KL 15</strong>”.</p>\n<p><strong>7</strong> – On the same page, there’s a second drop-down menu at the bottom<br/>of the page.<br/>Select<strong>“active</strong>” and confirm.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/5Q0-937-084-Q_Module09_Adaptation_disable_horn-34a976ae.webp\"/></figure>\n<p><strong>Line 2:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Anti-theft protection – Akustischer Alarm Signalhorn</strong>”.<br/><br/><strong>7</strong> – On the same page, there’s a second drop-down menu at the bottom<br/>of the page.<br/>Select<strong>“active</strong>” and confirm.</p>\n<p><strong>Line 3:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Anti-theft protection – Alarmsignal</strong>”.<br/><br/><strong>7</strong> – On the same page, you’ll find a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“frequency modulated</strong>” and confirm.</p>\n<p><strong>Line 4:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Anti-theft protection – DWA Alarmverzoegerung</strong>”.<br/><br/><strong>7</strong> – On this same page, there’s a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“driver door contact thatcham</strong>” and confirm.</p>\n<p><strong>Line 5:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Anti-theft protection – DWA Camper Modus</strong>”.<br/><br/><strong>7</strong> – On the same page, there’s a second drop-down menu at the bottom<br/>of the page.<br/>Select<strong>“active</strong>” and confirm.</p>\n<p><strong>Line 6:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Protection antivol – Sirenen Alarmzahl</strong>”.<br/><br/><strong>7</strong> – On the same page, you’ll find a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“10 alarms</strong>” and confirm.</p>\n<p><strong>Line 7:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Protection antivol – Verzoegerung Panikalarm</strong>”.<br/><br/><strong>7</strong> – On the same page, you’ll find a second drop-down menu at the bottom<br/>of the page.<br/>Select<strong>“2 sekunden verzoegerung</strong>” and confirm.</p>\n<p><strong>Line 8:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose “<strong><strong>Anti-theft Alarm System</strong></strong>”<strong> Anti-theft Alarm System</strong><br/><br/><strong>7</strong> – On the same page, there’s a second drop-down menu at the bottom<br/>of the page.<br/>Select<strong>“active</strong>” and confirm.</p>","tarraco-kn-activate-lane-assist-memory-function":"<p><strong>Purpose:</strong> to store the Lane Assist function in memory. If you deactivate it, the Lane Assist will not automatically resume the next time you start up.  <br/><br/><strong>Proceed :</strong> <br/><strong>1 </strong>– Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostic socket or OBDeleven box.<br/><br/><strong>2 </strong>– Switch on the ignition and run the VCDS program or the OBDeleven application.<br/><br/><strong>Line 1 (For Camera A5 5Q0 / 3Q0) :</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>” then click on “.<strong>A5 – Frt Sens. Drv.  Assist</strong>“.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on “<strong>Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose “<strong>Personalization of lane dept. warning Cl. 15 on  </strong>“<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu, but at the bottom<br/>of the page.<br/>On this menu, select<strong>“last setting </strong>” and confirm.</p>\n<hr/>\n<p><strong>Line 1 (For Camera A5 2Q0):</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>” then click on “.<strong>A5 – Frt Sens. Drv.  Assist</strong>“.<br/><br/><strong>4</strong> – Click on “<strong>Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>”.<br/><br/><strong>5</strong> – Select byte<strong>“09</strong>”<br/>Then check Bit<strong> 0-1</strong><strong>“03 Configuration_for_lane_departure_warning_Kl15, Last_setting</strong>”.</p>","tarraco-kn-activate-window-operation-with-ignition-off":"<p><strong>Purpose:</strong> Enables the windows to be operated (up/down) with the ignition off and the door open.  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – At the very top of this page, there is a drop-down menu.<br/>In this drop-down menu, select “<strong>Access control 2—Disable FH follow-up for Class 15.</strong>“<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu toward the bottom of the page.<br/>From this menu, select “<strong>active</strong>,” then confirm.</p>\n<p><strong>Line 2:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – At the very top of this page, there is a drop-down menu.<br/>From this drop-down menu, select “<strong>Access control 2—Cancel FH access follow-up when door opens</strong>.”<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu toward the bottom of the page.<br/>From this menu, select “<strong>not</strong> <strong>active</strong>,” then confirm.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/vitrecontactcoupevagcoding-1024x530-1c73d125.webp\"/></figure>","tarraco-kn-activate-deactivate-daytime-running-lights-drl-via-display":"<p><strong>Purpose:</strong> to activate/deactivate daytime running lights (DRL) from the CAR menu.  </p>\n<p>BE AWARE of your country’s regulations and vehicle inspection requirements regarding daytime running lights!  <br/>However, if you’re coding in your car to avoid using too much of your battery, this is a good solution…  </p>\n<p><br/>Procedure: <br/>1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket or OBDeleven.<br/><br/>2 – Switch on the ignition and run the VCDS program.<br/><br/>VCDS : </p>\n<p><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – At the very top of this page, there is a drop-down menu.<br/>In this drop-down menu, select “<strong>Daytime running lights—Tagfahrlicht—Activation possible via BAP or control sequence</strong>.”<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“active</strong>” and confirm.</p>\n<figure>\n</figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/5Q0-937-084-Q_Module09_Adaptation_feux_jour_drl-0a93900d.webp\"/></figure>\n<hr/>\n<p><strong>OBDeleven:</strong></p>\n<figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/obdeleven09-d37c6d29.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/obdelevenadapt-0d774aea.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/obdelevenaussenlicht-0747a95f.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/obdeleventagfahrlicht-78f4d30c.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/obdeleventagfahrlichtactive-e1f21fc0.webp\"/></figure>\n</figure>","tarraco-kn-activate-deactivate-windshield-wipers-on-key-removal":"<p><strong>Purpose:</strong> to activate windshield wiper stop when the key is removed (wipers stop directly in the position they were in) or to deactivate so that the wipers are in the parking position (in the windshield bay) when the key is removed.  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong> “.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong> “.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose “<strong><strong>Windshield wiper-Wischer stop bei KL15 aus</strong></strong>”<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, choose<strong>“active</strong>” (stop immediately on key removal) <em>or</em><strong>“inactive</strong>” (park position) and confirm.</p>","tarraco-kn-activation-of-high-beam-assist-light-assist":"<p><strong>Purpose:</strong> to activate the high beam assistant for vehicles with Sign Assist and/or Lane Assist options.  <br/></p>\n<p>Vehicle must be equipped with <strong>3Q0</strong> camera <br/><br/><br/><strong>Watch out! There are 4 lines of coding to do here.</strong> </p>\n<p><br/><strong>Proceed :</strong> <br/><strong>1 </strong>– Engine off, ignition off, connect your official VAG-COM VCDS cable to<br/>the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2 </strong>– Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on “<strong>Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Fernlicht_Assistent-Menu control high-beam assistant</strong>”.<br/><br/><strong>7</strong> – On the same page, there’s a second drop-down menu at the bottom<br/>of the page.<br/>Select<strong>“present</strong>” and confirm.<br/><br/><strong>Line 2:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Fernlicht_Assistent-Menu control high-beam assistant factory setting</strong>”.<br/><br/><strong>7</strong> – On the same page, there’s a second drop-down menu at the bottom<br/>of the page.<br/>Select<strong>“present</strong>” and confirm.</p>\n<p><strong>Line 3:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Fernlicht_Assistent-Extended_Fernlichtsteuerung</strong>”.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu, at the bottom<br/>of the page.<br/>On this menu, choose<strong> “AFS: FLA: BCM high beam” </strong>or<strong> “AFS: FLA: high beam over AFS</strong>”, then confirm.<br/><br/><strong>Line 4:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>” then click on “.<strong>A5 – Frt Sens. Drv.  Assist</strong>“.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Coding – 07</strong>” then click on<strong>“Long Coding Wizard</strong>”.<br/><br/><strong>6</strong> – Select byte<strong>“21</strong>”<br/>Then, in the<strong>“Bit 5-7</strong>” drop-down menu, select<strong>“20 AFS_coding_Light_Assist, High_Beam_Assist</strong>”.</p>","tarraco-kn-activation-of-progressive-interior-lighting":"<p><strong>Purpose:</strong> turns interior lights (door knobs, dashboard, center console) on and off gradually. By default, interior lights are switched on and off immediately with the headlights. Activating this function will result in a slow fade effect each time the interior lights are switched on or off.   (Interior Light Fade in/out)  <br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Interior lighting-KL58 Einschalten mit Rampe</strong>”.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“active</strong>” and confirm.</p>\n<figure>\n</figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/kl58rampe-e361a4ce.webp\"/></figure>\n<p>OBDeleven:</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/KL58rampeOBDeleven-1fdea7c1.webp\"/></figure>","tarraco-kn-automatic-door-unlocking-with-dsg-in-p-position":"<p><strong>Purpose:</strong> Automatically unlocks all doors when the DSG automatic transmission is shifted to the “P” position.  </p>\n<p><strong>Procedure: </strong><br/><strong>1 –</strong> Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2 –</strong> Switch on the ignition and run the VCDS program.</p>\n<p><strong>3 –</strong> Click on <strong>“Select”</strong>, then click on <strong>“09 – Cent. Elect.”</strong>.</p>\n<p><strong>4 –</strong> Click <strong>“Security Access – 16,”</strong> then enter the code <strong>“31347”</strong></p>\n<p><strong>5 –</strong> Click on <strong>“Adaptation – 10”</strong>.</p>\n<p><strong>6 –</strong> At the very top of this page, there is a drop-down menu.<br/>From this drop-down menu, select <strong>“Access control – Autounlock NAR”</strong></p>\n<p><strong>7 –</strong> On this same page, there is a second drop-down menu toward the bottom<br/>.<br/>From this menu, select <strong>“active</strong>, <strong>“</strong> then confirm.</p>","tarraco-kn-automatic-keyless-entry-kessy":"<p><strong>Purpose:</strong> Automatically locks the vehicle as soon as you leave it with the key, provided that the KESSY system (keyless entry, locking, and starting system) is installed. Unfortunately, the function that folds the exterior mirrors is not controlled and may need to be performed manually using the key if necessary.   </p>\n<p><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong> <br/><br/><strong>3</strong> – Click “<strong>Select</strong>,” then click “<strong>05 – Access/Start Authorization</strong>.”<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>“.<br/><br/><strong>5</strong> – Click “<strong>Encoding – 07</strong>,” then click “<strong>Long Coding Helper</strong>.”<br/><br/><strong>6</strong> – Select byte “<strong>2</strong>“<br/>. Then set bit “<strong>5</strong>” (module 5Q0) <em><strong>OR</strong></em> Bit “<strong>4</strong>” (Module 3Q0) <em>“Locking for Door Slamming active”</em></p>\n<p><strong>Line 2: </strong></p>\n<p><strong>3</strong> – Click “<strong>Select</strong>,” then click “<strong><strong>05 – Access Authorization/Startup</strong></strong>“.</p>\n<p><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>“.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – At the very top of this page, there is a drop-down menu.<br/>From this drop-down menu, select “<strong>internal_passive_entry_exit_byte1-passive_exit_door_slam_lock</strong>“<br/><br/><strong>7</strong> – On the same page, there’s a second drop-down menu at the bottom<br/>of the page.<br/>Select<strong>“Active</strong>” and confirm.</p>","tarraco-kn-change-warning-thresholds-for-icy-conditions":"<p><strong>Purpose:</strong> Allows you to select the outside temperature value for the risk of icy conditions for which the warning is displayed on the dashboard (Ice Warning).  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“17 – Instruments</strong>“.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Outsitde temperature p ice warning entry temperature</strong>” for the value at which the alert sounds to warn of frost. (Origin: 4°C)<br/>Then choose<strong>“Outsitde temperature p ice warning <strong><strong>exit</strong></strong> temperature</strong>” for the value at which the frost alert ends. (Origin: 6°C)  </p>\n<p><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom of the page.<br/>On this menu, choose the temperature value you want.</p>","tarraco-kn-changing-the-virtual-cockpit-display":"<p><strong>Purpose:</strong> to modify and customize the Active Info Display / Virtual Cockpit. Depending on the setting, the display of the counter and/or vmax is different.  </p>\n<p><br/><br/><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1 (To change counter background) :</strong></p>\n<p>3 – Click on “<strong>Select”</strong>, then click on “<strong>17- Instruments</strong>”.</p>\n<p>4 – Click on “<strong>Adaptation – 10</strong>”.</p>\n<p><strong>5 – </strong>On this page, at the very top, there is a drop-down menu. In this drop-down menu, select the “<strong>Tube illustration</strong>” / <strong>“Tube representation”</strong> channel.</p>\n<p><strong>6 </strong>– In the “<strong>Value:</strong>” option, select one of the following versions:</p>\n<p>Version 0</p>\n<p>Version 1</p>\n<p>Version 2</p>\n<p>Version 3 (Cupra bronze):</p>\n<figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/compteuribizacupra1-1024x768-56b72a58.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/compteuribizacupra2-1024x768-e817d7a4.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/compteuribizacupra3-1024x768-bf6fcca7.webp\"/></figure>\n</figure>\n<p>Version 8: Cupra</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/representationtubeseat-1024x740-3a5656a8.webp\"/></figure>\n<p>For Sport Cupra central counter see tuto :</p>\n<figure>\n<blockquote><a href=\"https://www.vag-coding.fr/seat/tarraco-kn/tarraco-kn-compteur-sport-cupra/\" rel=\"noopener\" target=\"_blank\">Tarraco (KN) – Compteur Sport Cupra</a></blockquote>\n</figure>\n<hr/>\n<p><strong>Line 2 (To modify Vmax) :</strong> </p>\n<p>3 – Click on “<strong>Select”</strong>, then click on “<strong>17- Instruments</strong>”.</p>\n<p>4 – Click on “<strong>Adaptation – 10</strong>”.</p>\n<p><strong>5 – </strong>On this page, at the very top, there is a drop-down menu. In this drop-down menu, select the “<strong>Tachometer end value</strong>” channel.</p>\n<p><strong>6 </strong>– In the “<strong>Value:</strong>” option, choose one of the 3 versions:  </p>\n<p>Version 0 – 260 km/h<br/>Version 2 – 240 km/h<br/>Version 3 – 300 km/h</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/speedometer-adapration-leon-5f-cupra-7cf08f02.webp\"/></figure>","tarraco-kn-comfort-flashing-light":"<p><strong>Purpose:</strong> to set the number of flashes for the “Comfort flashing” option.  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Turn signal control-Komfortblinken Blinkzyklen</strong>”.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom of the page.<br/>On this menu, choose between<strong>“3</strong>” and<strong>“5</strong>” and confirm.<br/></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/5Q0-937-084-Q_Module09_Adaptation_clignotant_confo-f1a2f919.webp\"/></figure>\n<p><em>Information: If, after coding, the number of flashes has not changed, on your MIB screen: CAR -&gt; Settings -&gt; Factory settings -&gt; Lighting (Your interior lighting configurations will also be reset).</em></p>","tarraco-kn-complete-opening-of-sunroof-with-remote-control":"<p><strong>Purpose:</strong> Allows the sunroof to open fully when opening with the remote control.  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – At the very top of this page, there is a drop-down menu.<br/>From this drop-down menu, select “<strong>Zugangskontrolle 2-SAD Komfort schliessen</strong>.”<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu toward the bottom<br/>.<br/>From this menu, select “<strong>Active</strong>” and then confirm.</p>\n<p><strong>Line 2:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – At the very top of this page, there is a drop-down menu.<br/>From this drop-down menu, select “<strong>Zugangskontrolle 2-SAD Komfort oeffnen</strong>.”<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu toward the bottom<br/>.<br/>From this menu, select “<strong>Active</strong>” and then confirm.</p>\n<p><strong>Line 3 (Optional, to open the sunroof completely):</strong><br/><br/><strong>3</strong> – Click “<strong>Select</strong>,” then click “<strong>CA – Sunroof</strong>.”<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – At the very top of this page, there is a drop-down menu.<br/>From this drop-down menu, select “<strong>Target position for comfort opening</strong>” / “<strong>Komfortfunktionen-Ziellage bei Komfortöffnen</strong>“<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu, but further down<br/>.<br/>From this menu, select “<strong>Sliding position </strong>” then click Submit.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/IMG_8953-1024x754-fa7d5332.webp\"/></figure>","tarraco-kn-correction-of-virtual-cockpit-fuel-consumption-display":"<p><strong>Purpose</strong>: to correct the fuel consumption display in the Virtual Cockpit.</p>\n<p><em>Note: these changes affect the display of instantaneous consumption, average consumption and fuel quantity.</em> </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/> 3 – Click on “<strong>Select</strong>”, then click on <strong>“17 – Instruments”</strong>. <strong>Procedure:</strong> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>4</strong> – Click on<strong>“Adaptation- 10</strong>”.</p>\n<p><strong>5</strong> – Select <strong>Channel:</strong> <em>“Display correction of <em>consumptions and operating range</em>”.</em></p>\n<p><em>Adjust consumption correction factor between 85% and 115%.</em> <em>(base value: 100)</em></p>\n<p><em>Example 1: Calculation based on volume per distance (e.g. l/100 km): DIS: 9.3 l/100 km. Actual: 9.8 l/100 km. (100, 9,8 / 9,73 ? 105,38) Channel 3 will be changed from 100 to 105.<br/>Example 2: Calculation based on volume distance (e.g. MPG is: DIS: 23 MPG. Actual: 24 MPG. (100, 23/24 and 95.83) Channel 3 will be changed from 100 to 96</em>.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/consomqb-7270c66a.webp\"/></figure>\n<p><em>Example 3: the consumption announced by the ODB is 5.9l/100km, after checking it is actually 6.3l/100km.<br/>Calculation of the rate to be entered: (6.3 * 100) / 5.9 = 106.78. The rate used will be 107%, and the consumption announced by the ODB will be a pessimistic 0.1l/100km.</em></p>\n<p>Consumption is immediately modified on the MMI.</p>","tarraco-kn-cupra-sport-meter":"<p><strong>Purpose</strong>: to activate Cupra’s central sport meter on the Virtual Cockpit screen.  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong> <br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“17 – Instruments</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>5</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose “<strong>Sport</strong>”.<br/><br/><strong>6</strong> – On the same page, there’s a second drop-down menu at the bottom<br/>of the page.<br/>Select “<strong>Display</strong>” and confirm.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/sport-view-9d939380.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/IMG_6987-dcd6f282.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/displaycupra-1024x768-ce68adbc.webp\"/></figure>","tarraco-kn-daytime-running-light-deactivation-drl-with-handbrake":"<p><strong>Purpose:</strong> to deactivate the daytime running lights (DRL) using the handbrake.  <br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Daytime running lights-Tagfahrlicht Dauerfahrlicht bei Handbremse abschalten</strong>“.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“active</strong>” and confirm.<br/></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/Golf-7-5G---Desactiver-les-feux-de-jours-DRL-avec--6d661897.webp\"/></figure>","tarraco-kn-deactivate-coupling-between-roller-blind-and-sunroof":"<p><strong>Purpose:</strong> cancels the coupling of roller blinds and panoramic sunroofs, allowing them to be adjusted separately.  </p>\n<p><br/><br/><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket or your OBDeleven box.<br/><br/> 2 – Switch on the ignition, then run the VCDS program or the OBDeleven application.<br/><br/><strong>Line 1:</strong><br/><br/> 3 – Click on<strong>“Select”</strong>, then click on<strong>“CA – Sunroof</strong>”. <strong>Procedure:</strong> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>4</strong> – Click on<strong>“Coding – 07</strong>” then<strong>“Long Coding Helper</strong>”.</p>\n<p><strong>5</strong> – Select byte<strong>“02</strong>”<br/>Then uncheck Bit<strong>“6</strong>”.</p>","tarraco-kn-deactivate-mirrorlink":"<p><strong>Purpose:</strong> Allows you to disable or remove MirrorLink from Full Link on the MIB. The MirrorLink service has not been natively available on Android since June 1, 2020. For a direct connection to Android Auto.   <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“5F – Electr. information</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>“.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Vehicle configuration-Mirror_link</strong>“.<br/><br/><strong>7</strong> – On the same page, you’ll find a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“Disabled</strong>” and confirm.</p>","tarraco-kn-deactivate-open-door-alarm-with-contact":"<p><strong>Purpose:</strong> to deactivate the alarm which is triggered when the door is opened and the contact is in position P.  <br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“17 – Instruments</strong>“.<br/><br/><strong>4</strong> – Click “<strong>Adaptation – 10</strong>.”<br/><br/><strong>5</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Ignition active message</strong>” / ”  <strong>Message ignition active. trigger </strong>  “<br/><br/><strong>6</strong> – On this same page, you’ll find a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“tbd</strong>” /<strong>“No display</strong>” / “<strong>Aucun affichage</strong>” then confirm.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/5Q0-937-084-Q_Module09_Adaptation_ignition_active_-e1e03128.webp\"/></figure>","tarraco-kn-deactivate-roller-blind-when-locking-unlocking":"<p><strong>Purpose:</strong> Allows you to disable the roller shade’s comfort mode when locking or unlocking.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1 (<strong>Disable</strong> the roller shade when the comfort lock is engaged</strong>) <strong>:</strong><br/><em>The roof roller shade closes when the comfort mode is activated. You can adjust this behavior so that the roof roller shade remains in its current position. </em></p>\n<p><strong>3</strong> – Click “ <strong>Select</strong>,” then click “ <strong><strong>CA – Sunroof</strong>.”</strong> </p>\n<p><strong>4</strong> – Click on <strong>“Adaptation –</strong> 10”</p>\n<p><strong>5</strong> – At the very top of this page, there is a drop-down menu.<br/>In this drop-down menu, select “<strong>IDE11842-MAS13330-Komfortfunktionen-Komfortschließen Dachrollo</strong>” / “<strong>Comfort Features – Comfort Closing Roof Shade</strong>“</p>\n<p><strong>6</strong> – On this same page, there is a second drop-down menu, but further down<br/>.<br/>From this menu, select “ <strong><strong>No Active</strong></strong> ” and then confirm.</p>\n<p><strong>Line 2 (Disable the roller shade when the comfort mode is activated</strong>)<strong>:</strong><br/><em>The roof roller shade opens when the “Comfort” mode is activated. You can adjust this behavior so that the roof roller shade remains in its current position. </em></p>\n<p><strong>3</strong> – Click “ <strong>Select</strong>,” then click “ <strong><strong>CA – Sunroof</strong>.”</strong> </p>\n<p><strong>4</strong> – Click on <strong>“Adaptation –</strong> 10”</p>\n<p><strong>5</strong> – At the very top of this page, there is a drop-down menu.<br/>In this drop-down menu, select “<strong>IDE11842-MAS13329-Komfortfunktionen-Komfortöffnen Dachrollo</strong>” / “<strong>Comfort Features – Comfort Opening of Roof Shade</strong>“</p>\n<p><strong>6</strong> – On this same page, there is a second drop-down menu toward the bottom<br/>.<br/>From this menu, select <strong>“No Active</strong> ” and then confirm.</p>","tarraco-kn-deactivate-switch-on-low-beam-message":"<p><strong>Purpose:</strong> Disables the warning message or dialog prompting the driver to turn on the low beams when the headlight switch is in position 0.  </p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/allumerfeuxdecroisement1-1024x609-756a4f05.webp\"/></figure>\n<p><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – At the very top of this page, there is a drop-down menu.<br/>In this drop-down menu, select “<strong>Außenlicht_uebergreifend-Fahrlichtwarnung_Hinweis_Konfig</strong>” / ” <strong>driving light_hint_config</strong> ”  <br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu toward the bottom of the page.<br/>From this menu, select “<strong>kein_Hinweis</strong>” and then confirm.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/allumerfeuxdecroisement2-f3950d1b.webp\"/></figure>","tarraco-kn-deactivate-activate-electric-handbrake-for-rear-brake-pad-change":"<p><strong>Purpose:</strong> to deactivate/activate the electric handbrake in maintenance mode in order to change/replace the rear brake pad/disc linings. (Lining change mode)  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostic socket or OBDeleven box.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program or the OBDeleven application.<br/><br/><br/>To begin, set the gear lever to P and remove the electric handbrake on the button. Check that there are no faults/errors before starting basic setup.<br/><br/><strong>3</strong> – Click on<strong>“Select</strong>” then click on<strong>“03 – ABS brake</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Basic setting – 04</strong>”.<br/><br/><strong>5</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Start trim change mode.</strong>”<br/><br/><strong>6</strong> – Click on<strong>“Go</strong>”.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/plaquettearriere-1024x629-2b32f223.webp\"/></figure>\n<p><br/><br/>A fault message will appear on your ODB indicating “<strong>Parking brake fault</strong>”, but this is normal and should be ignored<br/><br/> 7 – Wait for<strong>“Procedure complete</strong>” to be displayed<br/><br/> 8 – Once finished, return to the program until it closes<br/><br/> 9 – Switch off the vehicle’s ignition, then disconnect the VAG-COM cable<br/><br/><strong>10</strong> – <strong>Change the linings on both sides!</strong><br/><br/><br/></p>\n<p><strong>To reactivate the electric handbrake :</strong><br/><br/><br/><strong>11</strong> – With engine off and ignition switched off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>12</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>13</strong> – Click on<strong>“Select</strong>” then click on<strong>“03 – ABS brake</strong>”.<br/><br/><strong>14</strong> – Click on<strong>“Basic setting – 04</strong>”.<br/><br/><strong>15</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“End trim change mode.</strong>”<br/><br/><strong>16</strong> – Click on<strong>“Go</strong>”.<br/><br/><strong>17</strong> – Wait for<strong>“Procedure complete</strong>” display</p>","tarraco-kn-deactivation-of-parking-aid-activation-beep":"<p><strong>Purpose:</strong> to deactivate the beep when reverse gear is engaged or when parking assistance is activated manually.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click “ <strong>Select</strong>,” then click “ <strong>10 – Parking Assistance</strong>.”</p>\n<p><strong>4</strong> – Click “<strong>Security Access – 16</strong>,” then enter the code “<strong>71679</strong>“</p>\n<p><strong>5</strong> – Click on ” <strong>Adaptation – 10</strong> “.</p>\n<p><strong>6</strong> – Select ” <strong>Tonalité d’activation de l’aide au stationnement </strong>” / ” <strong>Park assist activation</strong> <strong>tone </strong>” / ” <strong>Aktivierungston für Einparkhilfe </strong>” from value list</p>\n<p><strong>7</strong> – Select ” <strong>Off”</strong> in the second value list  <br/></p>","tarraco-kn-delete-belt-alarm":"<p><strong>Purpose:</strong> to suppress the audible alarm and warning light in the Virtual Cockpit when driving without a seatbelt.  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“17 – Instruments</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding – 07</strong>” then<strong>“Long Coding Helper</strong>”.</p>\n<p><strong>5</strong> – Select byte <strong>0</strong>:<br/>Bit <strong>2-4</strong>: select <strong>“Seat Belt Warning inactive”</strong> from the drop-down list.</p>\n<p><strong><em>OR</em></strong></p>\n<p><strong>4</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose <strong>“Deactivate</strong> <strong>Seat belt warning”</strong> / <strong>“</strong> <strong>Désactiver l’avertissement de ceinture”.</strong> <br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu, at the bottom<br/>of the page.<br/>On this menu, select<strong>“Oui</strong>” /<strong>“Yes”</strong> and confirm.</p>\n<figure>\n</figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/8U0_920_940_Module17_Adaptation_desactivate_seat_b-77d3b532.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/voyant_ceinture_de_securite-296648a9.webp\"/></figure>","tarraco-kn-disable-am-frequency":"<p><strong>Purpose:</strong> to disable the AM radio frequency on the display (AM radio frequency is rarely used, unlike FM radio frequency).  </p>\n<p><br/><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“5F – Electr. information</strong>”.</p>\n<p><strong>4</strong> – Click on “<strong>Coding – 07</strong>”.</p>\n<p><strong>5</strong> – Click on “<strong>Long Coding Helper</strong>” .</p>\n<p><strong>6</strong> – Select Byte <strong>14</strong></p>\n<p>Set bit <strong>1</strong> <strong>“AM_disable</strong></p>\n<figure>\n</figure>","tarraco-kn-disable-rear-wiper-when-reversing":"<p><strong>Purpose:</strong> deactivates or reverses the rear wiper when reverse gear is engaged.  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Rear Window Wiper-Traenenwischen Heck</strong>”.<br/><br/><strong>7</strong> – On the same page, there’s a second drop-down menu at the bottom of the page.<br/>Select<strong>“active</strong>” to activate or<strong>“not active</strong>” to deactivate, then confirm.</p>","tarraco-kn-disable-the-safelock-feature":"<p><strong>Purpose:</strong> Allows you to disable the SafeLock feature, displaying the warning message “Check SAFELOCK! Owner’s manual!” on the ODB after the ignition is turned off. The vehicle can be unlocked from the inside even after it has been locked from the outside.   </p>\n<p><br/><em>Safelock is an anti-theft system that prevents thieves from gaining access to the car. This device locks the doors—both from the outside and the inside—when the driver activates the central locking remote control after leaving the vehicle.<br/>If occupants are still inside, they cannot open the doors or even lower the windows. The car can then become a veritable trap.  </em></p>\n<p><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong> “.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong> “.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose “<strong> <strong>ZV allgemein – ZV_ohne_Safe_Funktion</strong></strong>”<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“installed</strong>” and confirm.</p>\n<figure>\n<figure><img alt=\"safelock\" decoding=\"async\" loading=\"lazy\" src=\"img/safelock-860e326f.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/safelock2-3b72ec8c.webp\"/></figure>\n</figure>","tarraco-kn-door-lock-unlock-confirmation-beep-horn":"<p><strong>Purpose:</strong> to set confirmation of door locking/unlocking with beep (alarm) or horn.  <br/><br/><br/><strong>Warning!! There are 5 lines of code to write here—actually, 6. </strong> <em>(After programming, if it doesn’t work, enable the option on your screen in CAR – Open/Close Settings – check “Audible Confirmation”)</em> <br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – At the very top of this page, there is a drop-down menu.<br/>From this drop-down menu, select “<strong>Acknowledgement signals—Unlock acoustic feedback</strong>.”<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu located toward the bottom<br/>of the page.<br/>From this menu, select “<strong>Yes</strong>” and then confirm.<br/><br/><strong>Line 2:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – At the very top of this page, there is a drop-down menu.<br/>In this drop-down menu, select “<strong>Acknowledgement signals—Lock Akustische Rückmeldung</strong>.”<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu located toward the bottom<br/>of the page.<br/>From this menu, select “<strong>Yes</strong>” and then confirm.<br/><br/><strong>Line 3:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – At the very top of this page, there is a drop-down menu.<br/>From this drop-down menu, select “<strong>Acknowledgement signals-Akustische Rueckmeldung global</strong>.”<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“active</strong>” and confirm.<br/><br/><strong>Line 4:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – At the very top of this page, there is a drop-down menu.<br/>From this drop-down menu, select “<strong>Acknowledgement signals—Menuesteuerung Akustische Rückmeldung</strong>.”<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“active</strong>” and confirm.<br/><br/><strong>Line 5:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – At the very top of this page, there is a drop-down menu.<br/>From this drop-down menu, select “<strong>Acknowledgement signals—Duration of the acoustic feedback from the single horn</strong>.”<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu, but at the bottom<br/>of the page.<br/>On this, choose<strong>“normal</strong>” or<strong>“kurz</strong>” (for a short signal), then confirm.<br/><br/><strong><br/>!!! If your vehicle is not equipped with an alarm, here is the code you need to change to activate the horn </strong>  :<br/><br/><br/><strong>Line 6:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – At the very top of this page, there is a drop-down menu.<br/>From this drop-down menu, select “<strong>Acknowledgement signals—Akustische Rückmeldung Signalhorn</strong>.”<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“active</strong>” and confirm.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/IMG_7559-1024x495-1f01c127.webp\"/></figure>","tarraco-kn-easy-entry":"<p><strong>Purpose: </strong>automatically retracts the electric driver’s seat when the ignition is switched off and the door is opened (access aid).</p>\n<p><em><strong>This option can only be activated with a VCDS with experimental coding for the lo coding wizard.</strong></em><strong><em>ng! (MIB2 compatible) </em></strong></p>\n<p><strong>Procedure: </strong><br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>” then click on “.<strong>36 – Seat Mem. Drvr</strong>“.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select “<strong>Long coding wizard”</strong>:</p>\n<p>Byte <strong>3</strong>, Set bit <strong>1</strong> – “Easy_Entry_front,0=nict aktiv/1=aktiv</p>\n<p>For passenger seat if option: Byte <strong>6</strong>, Set bit <strong>3</strong> </p>\n<p>Then Byte <strong>9</strong> Set bit <strong>6</strong> – “automatic_func_key_memory_over_MMI, 0=nict aktiv/1=aktiv”.</p>\n<p><strong>Line 2:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“5F – Electr. information</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Car_Function_List_BAP_Gen2 – driver_seat_0x10</strong>”.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“active</strong>” and confirm.</p>\n<p><strong>Line 3:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“5F – Electr. information</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Car_Function_List_BAP_Gen2 – driver_seat_0x10_msg_bus</strong>”.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“Comfort data bus</strong>” and confirm.<br/><br/><strong>Line 4:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“5F – Electr. information</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Car_Function_Adaptations_Gen2 – menu_display_seat_configuration</strong>”.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“active</strong>” and confirm.<br/><br/><strong>Line 5:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“5F – Electr. information</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Car_Function_Adaptations_Gen2 – menu_display_seat_configuration_over_threshold_high</strong>”.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“active</strong>” and confirm.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/IMG_7341-1024x461-25c69cbd.webp\"/></figure>","tarraco-kn-enable-the-aircare-memory-function":"<p><strong>Purpose:</strong> Enables the AirCare function’s climate control memory feature. By default, this feature is disabled when you exit the vehicle. Once enabled, it remains active until you manually disable it.    <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click “<strong>Select</strong>,” then click “<strong>08 – Climatronic</strong>” (or “<strong>08 – Auto HVAC</strong>,” depending on your version of VCDS)<br/><br/><strong>4</strong> – Click on <strong>“Adaptation – 10”</strong>.<br/><br/><strong>5 –</strong> At the very top of this page, there is a drop-down menu.<br/>From this drop-down menu, select “<strong>IDE12229-Filterung Innenraumluft: speichern</strong>” / “<strong>Interior Air Filtration: Save</strong>“<br/><br/><strong>6</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“active</strong>” and confirm.<br/></p>","tarraco-kn-enable-ecotrainer-mode":"<p><strong>Purpose:</strong> Enables the “ECOTRAINER” mode: Displays the “ECO MODE” graph on the MIB2. <br/><br/><br/><strong>Warning! There are 2 lines of coding to do here. </strong> <br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“5F – Electr. information</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Car_Function_Adaptations_Gen2-menu_display_user_eco_rating</strong>”.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, choose the<strong>“active</strong>” value.<br/><br/><strong>Line 2:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“5F – Electr. information</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Car_Function_Adaptations_Gen2-menu_display_user_eco_rating_over_threshold_high</strong>”.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, choose the<strong>“active</strong>” value.<br/></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/seatecotrainer-scaled-67b4a159.webp\"/></figure>","tarraco-kn-engine-start-button-pulse":"<p><strong>Purpose:</strong> to activate the heartbeat when the Start Engine Stop button is pressed for the keyless start option.  </p>\n<p><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong> <br/><br/><strong>3</strong> – Click “<strong>Select</strong>,” then click “<strong>05 – Access/Start Authorization</strong>.”<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“ZAT_illumination_concept_mybeat_clamp58xt</strong>”.<br/><br/><strong>7</strong> – On the same page, there’s a second drop-down menu at the bottom<br/>of the page.<br/>Select<strong>“Active</strong>” and confirm.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/IMG_7456-0f43b3a6.webp\"/></figure>\n<p><strong>Line 2:</strong> <br/><br/><strong>3</strong> – Click “<strong>Select</strong>,” then click “<strong>05 – Access/Start Authorization</strong>.”<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“ZAT_illumination_modus_mybeat_clamp58xt</strong>”.<br/><br/><strong>7</strong> – On the same page, there’s a second drop-down menu at the bottom<br/>of the page.<br/>Select<strong>“Active</strong>” and confirm.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/IMG_7457-aa96d69a.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/IMG_7455-26181335.webp\"/></figure>","tarraco-kn-fan-speed-display-for-air-conditioning-in-auto-mode":"<p><strong>Purpose:</strong> to display fan speed when automatic air-conditioning mode is activated. (Climatronic fan speed display Auto mode)  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“08 – Climatronic</strong>” (or<strong>“08 – Auto HVAC</strong>”, depending on your VCDS version).<br/><br/><strong>4</strong> – Click on<strong>“Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>”.<br/><br/><strong>5</strong> – Select byte<strong>“11</strong>”<br/>Then check Bit<strong>“6</strong>”:<strong>“Blower Status Display in Auto-Mode active</strong>”.<br/></p>\n<figure>\n</figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/5G0-907-044-R_Module08_Byte11_v2-939963df.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/affichageclimautomqb-f32e9600.webp\"/></figure>","tarraco-kn-headlamp-flash-with-fog-lamps":"<p><strong>Purpose:</strong> Allows fog lamps to be used in addition to high beam. <br/><br/><strong>Warning!! There are 2 lines of code to enter here, or 4 lines if you have the corner lights or DRL fog lights option enabled. </strong> <br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – At the very top of this page, there is a drop-down menu.<br/>From this drop-down menu, select “<strong>Leuchte12NL LB45-Lichtfunktion B 12</strong>“<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“Lichthupe generell</strong>” and confirm.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/5Q0-937-084-Q_Module09_Adaptation_appel_phare_fog_-cd865d70.webp\"/></figure>\n<p><strong>Line 2:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.</p>\n<p><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.</p>\n<p><strong>6</strong> – At the very top of this page, there is a drop-down menu.<br/>From this drop-down menu, select “<strong>Leuchte13NL RB5-Lichtfunktion B 13</strong>“</p>\n<p><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“Lichthupe generell</strong>” and confirm.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/5Q0-937-084-Q_Module09_Adaptation_appel_phare_fog_-12f3ad2b.webp\"/></figure>\n<hr/>\n<p><strong>If the “corner lights” or “fog lights/DRL” option is enabled on channel B, select channel C:</strong></p>\n<p><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong><strong>“Leuchte12NL LB45-Lichtfunktion</strong> C 12</strong>“.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“Lichthupe generell</strong>” and confirm.</p>\n<p><strong>Line 2:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong><strong>“Leuchte12NL LB45-Dimmwert</strong><strong>CD12</strong></strong>“.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“100</strong>” and confirm.</p>\n<p><strong>Line 3:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.</p>\n<p><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.</p>\n<p><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong><strong>“Leuchte13NL RB5-Lichtfunktion</strong> C 13</strong>“.</p>\n<p><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“Lichthupe generell</strong>” and confirm.</p>\n<p><strong>Line 4:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong><strong><strong>“Leuchte13NL RB5-Dimmwert</strong></strong><strong>CD13</strong></strong>“.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“100</strong>” and confirm.</p>","tarraco-kn-front-assist-settings":"<p><strong>Purpose:</strong> activates the distance control on the screen menu, to adjust Front Assist parameters.  </p>\n<p><strong>Information:</strong> This setting is only possible if the HW part number of the control unit for remote control with <strong>2Q0 </strong>or <strong>3Q0 </strong>starts.<br/>Older control units starting with 5Q0 (usually with 7-byte coding) do not offer this option.</p>\n<p><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostic socket or OBDeleven box.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program or the OBDeleven application.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>” then click on “.<strong>13 –  <strong>Auto Dist. Reg</strong></strong>“.</p>\n<p><strong>4</strong> – Click on<strong>“Coding – 07</strong>” then<strong>“Long Coding Helper</strong>”.</p>\n<p><strong>5</strong> – Select byte<strong>“11</strong>”<br/>Then uncheck Bit<strong>“3</strong>”:<strong><strong>“adjustability_awv_pre_warning</strong></strong>”.</p>\n<p>OBDeleven: Select <strong>“<strong><strong>adjustability_awv_pre_warning</strong></strong>”</strong><br/>Change from “activated” to “Deactivated”.</p>\n<p>Bit 3 set: On/off warning :</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/frontassist1-f46c7de4.webp\"/></figure>\n<p>Bit 3 unchecked: Warning “early/mid/late/deactivated” :</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/frontassist2-30c3e6ba.webp\"/></figure>","tarraco-kn-heated-seat-memory":"<p><strong>How it works :</strong> When you switch on the heated seat(s), as soon as you remove the key from the ignition the setting is immediately switched off. With this activation, when you switch the ignition back on, the seat will have returned to the level at which you left it.  </p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>” then click on<strong>“08 – Climatronic</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>5</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose  </p>\n<p>“<strong>Retention of driver’s seat heater level</strong>” for <strong>Driver’s seat heater memory</strong></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/3AA-907-044-AG_Module08_Adaptation_retention_of_dr-51646659.webp\"/></figure>\n<p>and/or<strong>“Retention of passenger’s seat heater level</strong>” for <strong>Passenger seat heater memory</strong></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/3AA-907-044-AG_Module08_Adaptation_retention_of_pa-61b11e06.webp\"/></figure>\n<p><br/><br/><strong>6</strong> – On the same page, there’s a second drop-down menu at the bottom<br/>of the page.<br/>Select<strong>“active</strong>” and confirm.</p>","tarraco-kn-hill-start-assist":"<p><strong>Purpose:</strong> Allows you to adjust the operation of Hill Start Assist. (Hill Hold)   <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“03 – ABS</strong><strong>Brakes </strong>”.<br/><br/><strong>4</strong> – Click “<strong>Adaptation – 10</strong>.”<br/><br/><strong>5</strong> – At the very top of this page, there is a drop-down menu.<br/>From this drop-down menu, select “<strong>Hill Start Assistant</strong>.”<br/><br/><strong>6 – </strong> On this same page, there is a second drop-down menu located toward the bottom<br/>.<br/>From this menu, select the value based on your preference:</p>\n<ul>\n<li>“<strong>normal</strong>” (default value)</li>\n<li>“<strong>Early</strong>” (faster triggering)</li>\n<li>“<strong>Late”</strong> triggering</li>\n</ul>\n<p>then click “Submit.”</p>","tarraco-kn-increase-gas-pedal-sensitivity":"<p><strong>Purpose:</strong> to increase accelerator pedal sensitivity. (better acceleration response with DSG, more significant than with manual).  <br/><br/>Proceed : <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/></p>\n<p><strong>Line 1:</strong> <br/><br/> 3 – Click on<strong>“Select”</strong>, then click on<strong>“44 – Steering Assistance</strong>“.</p>\n<p><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“19249</strong>“.  </p>\n<p><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Commutation profil de conduite</strong>” /<strong>“Driving profile switchover</strong>”.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu, but at the bottom<br/>of the page.<br/>On this, choose the value: “<strong><em>directly: controlled by threshold value</em></strong>” / “<em><strong>Direct controlled over threshold value</strong></em>” then confirm.</p>\n<figure>\n</figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/IMG_7198-330b03e4.webp\"/></figure>","tarraco-kn-interior-lighting-deactivated-when-trunk-is-opened":"<p><strong>Purpose:</strong> deactivates interior lighting when only the trunk is opened.  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Interior lighting Innenlicht-bei offenem Heckdeckel einschalten</strong>”.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“inactive</strong>” and confirm.</p>","tarraco-kn-key-operation-even-with-ignition-on":"<p><strong>Purpose:</strong> Allows you to use the key and lock the vehicle with the ignition switched on or the engine running. (Very practical with a Keyless Kessy key)  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Access control-Funk bei Klemme 15 ein</strong>”.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“active</strong>” and confirm.</p>","tarraco-kn-lane-assist-activation":"<p><strong>Purpose:</strong> to activate Lane Assist for vehicles with Sign Assist and/or Light Assist options.  </p>\n<p>Vehicle must be equipped with <strong>3Q0</strong> or <strong>2Q0</strong> camera (different A5 coding)  <br/><br/><br/><strong>Watch out! There are 12 lines (3Q0) or 16 lines (2Q0) of coding to do here.</strong> <br/><br/><strong>Proceed :</strong> <br/><strong>1 </strong>– Engine off, ignition off, connect your official VAG-COM VCDS cable to<br/>the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2 </strong>– Switch on the ignition and run the VCDS program.<br/><br/></p>\n<h3><strong>For module A5 for camera 3Q0 :</strong><br/></h3>\n<p><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>” then click on “.<strong>A5 – Frt Sens. Drv.  Assist</strong>“.<br/><br/><strong>4</strong> – Click on “<strong>Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>”.<br/><br/><strong>5</strong> – Select byte<strong>“16</strong>”<br/>Then check Bit<strong> 7</strong><strong>“Lane departure warning system (HCA) active / installed [PR-7Y9]</strong>”.</p>\n<p><em>Or</em> byte <strong>00</strong>,bit <strong>0</strong><br/><br/><strong>Line 2 (if available):</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>” then click on “.<strong>A5 – Frt Sens. Drv.  Assist</strong>“.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Switch-on state of lane departure warning</strong>” /<strong>“HCA_On_State</strong>”.<br/><br/><strong>7</strong> – On this same page, you’ll find a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“Menu</strong>” and confirm.</p>\n<p><strong>Line 3 (if available):</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>” then click on “.<strong>A5 – Frt Sens. Drv.  Assist</strong>“.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“HCA_Warning_Intensity</strong>”.<br/><br/><strong>7</strong> – On this same page, you’ll find a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“Menu</strong>” and confirm.<br/><br/><strong>Line 4:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>” then click on “.<strong>A5 – Frt Sens. Drv.  Assist</strong>“.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on “<strong>Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“BAP_Personalisierung</strong>” / <strong>BAP_Personalization</strong>“.<br/><br/><strong>7</strong> – On the same page, there’s a second drop-down menu at the bottom<br/>of the page.<br/>Select<strong>“not activated</strong>” and confirm.</p>\n<p><strong>Line 5:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>” then click on “.<strong>A5 – Frt Sens. Drv.  Assist</strong>“.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Intervention Moment</strong>”/<strong>“Point_of_intervention</strong>”.<br/><br/><strong>7</strong> – On the same page, you’ll find a second drop-down menu at the bottom<br/>of the page.<br/>Select<strong>“Late</strong> or <strong>Menu</strong>” and confirm.</p>\n<p><strong>OR</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>” then click on “.<strong>A5 – Frt Sens. Drv.  Assist</strong>“.<br/><br/><strong>4</strong> – Click on “<strong>Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>”.<br/><br/><strong>5</strong> – Select byte<strong>“14</strong>”<br/>Then check Bit<strong> 5-7</strong><strong>“Point_of_intervention, setting_via_menu</strong>”.<br/><br/><br/><strong>Line 6 (if available):</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>” then click on “.<strong>A5 – Frt Sens. Drv.  Assist</strong>“.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on “<strong>Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose “<strong>Personalization of lane dept. warning Cl. 15 on  </strong>“<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu, but at the bottom<br/>of the page.<br/>On this menu, select<strong>“last setting </strong>” and confirm.</p>\n<p><strong>FIN A5 3Q0</strong></p>\n<h3><strong>For A5 module for camera 2Q0 :</strong></h3>\n<p><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>” then click on “.<strong>A5 – Frt Sens. Drv.  Assist</strong>“.<br/><br/><strong>4</strong> – Click on “<strong>Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>”.<br/><br/><strong>5</strong> – Select byte<strong>“08</strong>”<br/>Then check Bit<strong> 5-7</strong><strong>“A0 Point_of_intervention, late_setting_over_menu</strong>”.</p>\n<p><strong>Line 2:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>” then click on “.<strong>A5 – Frt Sens. Drv.  Assist</strong>“.<br/><br/><strong>4</strong> – Click on “<strong>Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>”.<br/><br/><strong>5</strong> – Select byte<strong>“09</strong>”<br/>Then check Bit<strong> 0-1</strong><strong>“03 Configuration_for_lane_departure_warning_Kl15, Last_setting</strong>”.</p>\n<p><strong>Line 3:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>” then click on “.<strong>A5 – Frt Sens. Drv.  Assist</strong>“.<br/><br/><strong>4</strong> – Click on “<strong>Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>”.<br/><br/><strong>5</strong> – Select byte<strong>“09</strong>”<br/>Then check Bit<strong> 2-3</strong><strong>“0C Lane_assist_system_mode, Selection_over_menu</strong>”.</p>\n<p><strong>Line 4:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>” then click on “.<strong>A5 – Frt Sens. Drv.  Assist</strong>“.<br/><br/><strong>4</strong> – Click on “<strong>Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>”.<br/><br/><strong>5</strong> – Select byte<strong>“09</strong>”<br/>Then check Bit<strong> 7</strong><strong>“HC, 0 = not_coded / 1 = coded</strong>”.</p>\n<p><strong>Line 5:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>” then click on “.<strong>A5 – Frt Sens. Drv.  Assist</strong>“.<br/><br/><strong>4</strong> – Click on “<strong>Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>”.<br/><br/><strong>5</strong> – Select byte<strong>“17</strong>”<br/>Then check Bit<strong> 0</strong><strong>“Hc_messages, 0 = not_coded / 1 = coded</strong>”.</p>\n<p><strong>Line 6:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>” then click on “.<strong>A5 – Frt Sens. Drv.  Assist</strong>“.<br/><br/><strong>4</strong> – Click on “<strong>Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>”.<br/><br/><strong>5</strong> – Select byte<strong>“17</strong>”<br/>Then check Bit<strong> 1-3</strong><strong>“02 HC_Warn_Intensity Set, Setting_over_Menu</strong>”.</p>\n<p><strong>Line 7:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>” then click on “.<strong>A5 – Frt Sens. Drv.  Assist</strong>“.<br/><br/><strong>4</strong> – Click on “<strong>Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>”.<br/><br/><strong>5</strong> – Select byte<strong>“17</strong>”<br/>Then check Bit<strong> 5-7</strong><strong>“20 Hc_variant, Variant_1” or “00 Hc_variant, Variant_0</strong>”.</p>\n<p><strong>Line 8:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>” then click on “.<strong>A5 – Frt Sens. Drv.  Assist</strong>“.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on “<strong>Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Switch-on status of lane departure warning system</strong>”.<br/><br/><strong>7</strong> – On the same page, there’s a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“on (setting via menu) </strong>” ” then confirm.</p>\n<p><strong>FIN A5 2Q0</strong></p>\n<p><br/><strong>Continued coding for all 3Q0 and 2Q0 cameras:</strong><br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“5F – Electr. information</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6-</strong> On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Car_Function_List_BAP_Gen2-LDW_HCA_0x19</strong>”.<br/><br/><strong>7</strong> – On the same page, you’ll find a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“activated</strong>” and confirm.</p>\n<p><strong>Line 2:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“5F – Electr. information</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6-</strong> On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Car_Function_List_BAP_Gen2-LDW_HCA_0x19_msg_bus</strong>”.<br/><br/><strong>7</strong> – On the same page, you’ll find a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“data Extended</strong>” and confirm.<br/><br/><strong>Line 3:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“5F – Electr. information</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Car_Function_Adaptations_Gen2-menu_display_Lane_Departure_Warning</strong>”.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu, but at the bottom<br/>of the page.<br/>On this menu, choose<strong>“activated</strong>” and confirm.<br/><br/><strong>Line 4:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“5F – Electr. information</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Car_Function_Adaptations_Gen2-menu_display_Lane_Departure_Warning_over_threshold_high</strong>”.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu, but at the bottom<br/>of the page.<br/>On this menu, choose<strong>“activated</strong>” and confirm.</p>\n<p><strong>Line 5:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“17 – Instruments</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>”.<br/><br/><strong>5</strong> – Select byte<strong>“4</strong>”<br/>Then check Bit<strong>“6</strong>”:<strong>“Lane Maintenance Assist installed</strong>”.<br/><br/><strong>Line 6:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“17 – Instruments</strong>”.<br/><br/><strong>4</strong> – Click on “<strong>Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>”.<br/><br/><strong>5</strong> – Select byte<strong>“11</strong>”<br/>Then check Bit<strong>“1</strong>”:<strong>“Lane Maintenance Assist information (BAP) installed/active</strong>”.</p>\n<p><strong>Line 7:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“44 – Steering Assist</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“19249</strong>”.<br/><br/><strong>5</strong> – Click on “<strong>Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>”.<br/><br/><strong>6</strong> – Select byte<strong>“3</strong>”<br/>Then check Bit<strong>“0</strong>”:<strong>“Lane Assist installed</strong>”.</p>\n<p><em>Or</em> byte <strong>0</strong>, bit <strong>4</strong> <em>or</em> byte <strong>4</strong>, bit <strong>0</strong></p>\n<p><strong>Line 8:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“10 – Assistance Stationt</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“71679</strong>”.<br/><br/><strong>5</strong> – Click on “<strong>Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>”.<br/><br/><strong>6</strong> – Select byte<strong>“3</strong>”<br/>Then check Bit<strong>“5</strong>”:<strong>“Lane departure warning with steering assistance installed</strong>”.</p>","tarraco-kn-lane-assist-settings":"<p><strong>Purpose</strong>: Adjusts lane departure warning, driver inactivity deactivation threshold, steering assist intensity and steering wheel vibration intensity.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition and run the VCDS program.</p>\n<h4><strong>Adjusting the driver inactivity deactivation threshold</strong>:</h4>\n<p><strong>3</strong> – Click on ” <strong>Select”</strong>, then click on “Select”.<strong><strong>A5 – Front Camera</strong></strong>” .</p>\n<p><strong>4</strong> – Click on “<strong>Security Access – 16</strong>” then enter the code “<strong>20103</strong>”</p>\n<p><strong>5</strong> – Click on “<strong>Adaptation – 10</strong>”.</p>\n<p><strong>6 </strong>– Select Channel <em>:</em><em>“Deactivation threshold for lane departure warning Driver inactivity</em>” or <em>“Deaktivierungsschwelle Fahrerinaktivität”.</em><br/></p>\n<p>Adjust value accordingly<br/>Setting range:<br/><br/>– early (deactivates Lane Assist within 7 seconds)<br/>– medium (factory setting, deactivates Lane Assist within 7 to 10 seconds)<br/>– late (deactivates Lane Assist within 11 to 15 seconds)</p>\n<h4><strong>Adjust the intensity of the steering assist</strong>:</h4>\n<p><strong>3</strong> – Click on ” <strong>Select”</strong>, then click on “Select”.<strong><strong>A5 – Front Camera</strong></strong>” .</p>\n<p><strong>4</strong> – Click on “<strong>Security Access – 16</strong>” then enter the code “<strong>20103</strong>”</p>\n<p><strong>5</strong> – Click on “<strong>Adaptation – 10</strong>”.</p>\n<p><strong>6 </strong>– Select Channel <em>:</em> <em>“Lane Departure Warning Intensity Steering Assistance”</em> or <em>“Intensität Lenkradunterstützung”.</em><br/></p>\n<p>Adjust value accordingly<br/>Setting range:<br/><br/>– low (Lane Assist switches off earlier depending on ambient conditions, as less/more sensitive steering interventions are carried out)<br/>– medium (factory setting)<br/>– high (Lane Assist switches off later depending on ambient conditions, as more/more intensive steering interventions are carried out)</p>\n<h4><strong>Adjust steering wheel vibration intensity</strong>:</h4>\n<p><strong>3</strong> – Click on ” <strong>Select”</strong>, then click on “Select”.<strong><strong>A5 – Front Camera</strong></strong>” .</p>\n<p><strong>4</strong> – Click on “<strong>Security Access – 16</strong>” then enter the code “<strong>20103</strong>”</p>\n<p><strong>5</strong> – Click on “<strong>Adaptation – 10</strong>”.</p>\n<p><strong>6 </strong>– Select Channel <em>:</em><em>“Steering wheel vibration intensity</em>” or <em>“Intensität Lenkradvibration”.</em><br/></p>\n<p>Adjust value accordingly<br/>Setting value range:<br/><br/>– low<br/>– medium (factory setting)<br/>– high</p>","tarraco-kn-lap-timer":"<p><strong>Purpose:</strong> to add the stopwatch to the Virtual Cockpit.  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“17 – Instruments</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>” .<br/><br/><strong>5</strong> – Select byte<strong>“1</strong>”<br/>Then check Bit<strong>“3</strong>”:<strong>“Lap Timer active</strong>”.</p>\n<figure>\n</figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/GOLF-7-VAGCOM---CHECK-DES-AIGUILLES-1-dab4b41b.webp\"/></figure>","tarraco-kn-license-plate-illumination-open-trunk":"<p><strong>Purpose:</strong> turns on license plate illumination when trunk / tailgate is open.  <br/><br/><br/><strong>Warning! There are 3 lines of coding to do here. </strong> <br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong><strong>“Leuchte 25KZL HA59</strong> – Lichtfunktion C 25</strong>”.<br/><br/><strong>7</strong> – On this same page, there’s a second drop-down menu at the bottom<br/>of the page.<br/>On this, choose the value<strong>“Heckdeckel Offen</strong>” and confirm. <em>(origin : nicht aktiv)</em><br/><br/><br/><strong>Line 2:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong><strong>“Leuchte 25KZL HA59</strong> – Dimmwert CD 25</strong>”.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu, but at the bottom<br/>of the page.<br/>On this menu, select<strong>“100</strong>” and confirm. <em>(origin : 0)</em></p>\n<p><strong>Line 3:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Leuchte25KZL HA59 – Dimming Direction CD 25</strong>”.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu, but towards the bottom<br/>of the page.<br/>On the latter, choose<strong>“maximise</strong>” then validate.</p>","tarraco-kn-light-assist-always-active":"<p><strong>Purpose:</strong> automatically activates the high beam assistant on start-up if it was active before the ignition was switched off.  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Assistance light functions-Fernlichtassistent Reset</strong>”.<br/><br/><strong>7</strong> – On the same page, there’s a second drop-down menu at the bottom<br/>of the page.<br/>Select<strong>“not active</strong>” and confirm.<br/></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/fernlicht-6b04f01d.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/lightassist-1a9a5499.webp\"/></figure>","tarraco-kn-lower-passenger-mirror-when-reversing":"<p><strong>Purpose:</strong> Automatically lowers the passenger-side rearview mirror when reversing. </p>\n<p>The mirror adjustment button must be in the “<strong>R</strong>” position, and the feature must be enabled on the display for the passenger-side mirror to lower automatically.</p>\n<p><strong>Warning!! There are 3 lines of code to write here.  <br/></strong></p>\n<p><strong>Procedure: </strong><br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“52 – Passenger door</strong>“.</p>\n<p><strong>4</strong> – Click on<strong>“Coding – 07</strong>“, then on<strong>“Long Coding Helper</strong>“.</p>\n<p><strong>5</strong> – Select byte “<strong>4</strong>“<br/>Then check bit “<strong>2</strong>“: “<strong>Reserve Gear Mirror Dipping active</strong>“<br/>and bit “<strong>3</strong>“: “<strong>Position Memory for Reserve Gear Mirror Dipping active</strong>“</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/Golf-7-Abaisser-le-retroviseur-passager-lors-de-la-9710a97c.webp\"/></figure>\n<p><strong>Line 2:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click “<strong>Security Access – 16</strong>,” then enter the code “<strong>31347</strong>.”</p>\n<p><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.</p>\n<p><strong>6</strong> – At the very top of this page, there is a drop-down menu.<br/>From this drop-down menu, select “<strong>Access Control 2-Spieglelabsenkung bei Rueckwaertsfahrt</strong>“</p>\n<p><strong>7</strong> – On this same page, there is a second drop-down menu near the bottom of the page.<br/>From this menu, select “<strong>active</strong>” and then confirm.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/5Q0-937-084-Q_Module09_Adaptation_abaisser_retro-3ad889c2.webp\"/></figure>\n<p><strong>Line 3:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click “<strong>Security Access – 16</strong>,” then enter the code “<strong>31347</strong>.”</p>\n<p><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.</p>\n<p><strong>6</strong> – At the very top of this page, there is a drop-down menu.<br/>From this drop-down menu, select “<strong>Access Control 2-Menuesteuerung Spieglelabsenkung</strong>.”</p>\n<p><strong>7</strong> – On this same page, there is a second drop-down menu near the bottom of the page.<br/>From this menu, select “<strong>active</strong>” and then confirm.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/5Q0-937-084-Q_abaisser-retro-marche-arriere-golf-m-a227e647.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/vw_golf7_5g_abaisser_retroviseur_marche_arriere-97-e91b72d8.webp\"/></figure>","tarraco-kn-microphone-sensitivity-adjustment":"<p><strong>Purpose:</strong> to adjust the intensity of the hands-free system’s microphone.  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“5F – Electr. information</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Microphone sensitivity</strong>” or “<strong>Mikrofonempfindlichtkeit</strong>”.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom of the page.<br/>On this menu, choose a value expressed in<strong>“dB</strong>” (default value<strong>“0 dB</strong>”) then validate.<br/></p>","tarraco-kn-mirror-folding-adjustment-by-remote-control":"<p><strong>Purpose:</strong> Allows you to set the option to fold the side mirrors using the remote control when locking the vehicle. <br/><br/><br/><em>The vehicle must be equipped with the “Power-folding side mirrors” option</em> <em>!</em> <br/><br/><br/><br/><strong>Proceed :</strong> <br/><strong>1 </strong>– Engine off, ignition off, connect your official VAG-COM VCDS cable to<br/>the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2 </strong>– Switch on the ignition and run the VCDS program.<em><br/></em><br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Access Control 2-Funk Spiegelanklappung Modus</strong>“.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu located toward the bottom<br/>.<br/>From this menu, select the value that suits your needs, then confirm.</p>\n<ul>\n<li>Default: <strong>“by convenience operation via remote control key”</strong> = press and hold the button on the key fob to fold the outside mirrors.</li>\n<li>Alternative: <strong>“by look command via remote control key”</strong> “by looking command via the remote control key” = briefly press the button on the key fob to fold the side mirrors.</li>\n</ul>","tarraco-kn-modify-power-steering-hardness":"<p><strong>Purpose:</strong> to adjust the hardness of the power steering for a softer steering wheel (Comfort) or a harder sporty one (Dynamic). <br/>Warning: if you have the driving mode selection, do not modify! <br/><br/><strong>Procedure </strong>: <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition and run the VCDS program. Procedure: 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>Line 1:</strong> <br/><br/> 3 – Click on<strong>“Select”</strong>, then click on<strong>“44 – Steering Assistance</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“19249</strong>”.  </p>\n<p><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/> 6 – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Courbes caractéristiques d’assistance de direction</strong>” /<strong>“Characteristic curve of steering assistance</strong>”<br/><br/> 7 – On this same page, there is a second drop-down menu but towards the bottom<br/>of the page.<br/>On this, choose the value:<strong>“Confort</strong>” or <strong>“Dynamic”</strong> then validate.</p>\n<p>selection_by_charisma: You have the driving modes, do not modify this value otherwise you will lose the hardness of the steering wheel according to your driving mode!  </p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/steeringassistance-1024x506-c5ba8daa.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/assistancedirection-scaled-eed591de.webp\"/></figure>","tarraco-kn-needle-check":"<p><strong>Purpose:</strong> to activate the scanning of the speedometer needles when the car is started. (Works with Virtual Cockpit) (Needle Sweep)  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“17 – instruments</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>”.<br/><br/><strong>5</strong> – Select byte<strong>“1</strong>”<br/>Then check Bit<strong>“0</strong>”:<strong>“Gauge Test/Needle Sweep (Stading) active</strong>”.<br/></p>\n<figure>\n</figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/GOLF-7-VAGCOM---CHECK-DES-AIGUILLES-1-dab4b41b.webp\"/></figure>","tarraco-kn-oil-temperature-on-virtual-cockpit":"<p><strong>Purpose:</strong> to display oil temperature on the Virtual Cockpit.  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“17 – Instruments</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>” .<br/><br/><strong>5</strong> – Select byte<strong>“10</strong>”<br/>Then check Bit<strong>“1</strong>”:<strong>“Display Oil Temperature</strong>”.</p>\n<figure>\n</figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/temperature-huile-vagcoding-ef203ab4.webp\"/></figure>","tarraco-kn-panel-display-on-virtual-cockpit":"<p><strong>Purpose:</strong> displays speed limit signs in the Virtual Cockpit (Sign Assist).   <br/><br/><br/>Vehicle must be equipped with <strong>3Q0</strong> camera <br/><br/><br/><strong>Warning! There are 9 lines of coding to do here. </strong> <br/><br/><strong>Proceed :</strong> <br/><strong>1 </strong>– Engine off, ignition off, connect your official VAG-COM VCDS cable to<br/>the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2 </strong>– Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“5F – Electr. information</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Car_Function_List_BAP_Gen2-traffic_sign_recognition_0x21</strong>”.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu, but at the bottom<br/>of the page.<br/>On this menu, choose<strong>“activated</strong>” and confirm.</p>\n<p><strong>Line 2:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“5F – Electr. information</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6 –</strong> On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Car_Function_List_BAP_Gen2-traffic_sign_recognition_0x21_msg_bus</strong>”.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“data Extended</strong>” and confirm.<br/><br/><strong>Line 3:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“5F – Electr. information</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6 –</strong> On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Car_Function_Adaptations_Gen2-menu_display_road_sign_identification</strong>”.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, choose<strong>“activated</strong>” and confirm.</p>\n<p><strong>Line 4:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“5F – Electr. information</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6 –</strong> On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Car_Function_Adaptations_Gen2-menu_display_road_sign_identification_over_threshold_high</strong>”.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, choose<strong>“activated</strong>” and confirm.<br/><br/><strong>Line 5:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>” then click on “.<strong><strong>5F – Information Electr.</strong></strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>”.<br/><br/><strong>6</strong> – Select byte<strong>“24</strong>”<br/>Select Bit <strong>6</strong><br/><br/><strong>Line 6:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>” then click on “.<strong>A5 – Frt Sens. Drv.  Assist</strong>“.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>”.<br/><br/><strong>6</strong> – Select byte<strong>“16</strong>”<br/>Then, in the Bit <strong>4</strong> drop-down menu, select<strong>“Traffic sign recognition (VZE) active [PR-QR9]</strong>”.<br/><br/><strong>Line 7<strong> (Optional)</strong>:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>” then click on “.<strong>A5 – Frt Sens. Drv.  Assist</strong>“.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Display end of speed limit symbol</strong>”.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, choose<strong>“activated</strong>” and confirm.</p>\n<p><strong>Line 8:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>” then click on “.<strong>A5 – Frt Sens. Drv.  Assist</strong>“.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Road Sign Detection Fusion Mode</strong>” /<strong>“Détection des panneaux de signalisation mode fusion</strong>”.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, choose<strong>“Traffic sign detection</strong>” to use camera recognition only, or<strong>“Traffic sign fusion</strong>” for camera + gps speed, then confirm.<br/><br/><strong>Line 9:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“17 – Instruments</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>”.<br/><br/><strong>6</strong> – Select byte<strong>“5</strong>”<br/>Then check Bit<strong>“2</strong>”:<strong>“Traffic Sign Recognition installed</strong>”.</p>","tarraco-kn-rear-lights-activated-with-daytime-running-lights-drl":"<p><strong>Purpose:</strong> Enables the rear lights to turn on when the daytime running lights (Scandinavian DRL) are activated (This method turns on the instrument panel lights) <br/><br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on “<strong>Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – At the very top of this page, there is a drop-down menu.<br/>In this drop-down menu, select “<strong>Daytime running lights—Tagfahrlicht—Dauerfahrlicht activated in addition to parking lights</strong>.”<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu near the bottom of the page.<br/>From this menu, select “<strong>active</strong>” and then confirm.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/5Q0-937-084-Q_Module09_Adaptation_feux_arriere_drl-eff83f7a.webp\"/></figure>","tarraco-kn-make-up-quantity-display-on-virtual-cockpit":"<p><strong>Purpose:</strong> Displays the amount of fuel needed to completely fill your tank on the Virtual Cockpit.  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“17 – Instruments</strong>“.<br/><br/><strong>4</strong> – Click on<strong>“Coding – 07</strong>“, then on<strong>“Long Coding Helper</strong>“.<br/><br/><strong>5</strong> – Select byte “<strong>10</strong>“<br/>. Then check bit “<strong>4</strong>“: “Volume to Be Replenished”</p>\n<p>If it’s a hidden bit, you need to replace the <strong>0</strong> with a <strong>1</strong> in “<strong>Binary</strong>.”</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/Golf-MKVII-Affichage-quantite-carburant-ODB-1024x3-6098b6ed.webp\"/></figure>","tarraco-kn-reprogramming-a-new-battery":"<p><strong>Purpose:</strong> Allows you to reprogram or recode all data for the new battery after it has been replaced. <br/><br/><br/><strong>Warning! There are 5 lines of coding to do here. </strong> <br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click “<strong>Select</strong>,” then click “<strong>19 – CAN Gateway</strong>.”<br/><br/><strong>4</strong> – Click ” <strong>Adaptation – 10</strong>.”<br/><br/><strong>5</strong> – At the very top of this page, there is a drop-down menu.<br/>From this drop-down menu, select “<strong>Battery Adaptation—Nominal Battery Capacity</strong>.”<br/><br/><strong>6</strong> – On this same page, there is a second drop-down menu toward the bottom<br/>.<br/>From this menu, select the rated capacity listed on your battery. For example: “<strong>70Ah</strong>“<br/><br/><strong>Line 2:</strong><br/><br/><strong>3</strong> – Click “<strong>Select</strong>,” then click “<strong>19 – CAN Gateway</strong>.”<br/><br/><strong>4</strong> – Click “<strong>Adaptation – 10</strong>.”<br/><br/><strong>5</strong> – At the very top of this page, there is a drop-down menu.<br/>From this drop-down menu, select “<strong>Battery Adaptation—Battery Technology</strong>.”<br/><br/><strong>6</strong> – On this same page, there is a second drop-down menu further down<br/>.<br/>From this menu, select the corresponding value<br/>. For example: For the VARTA E39, select “<strong>Etoffe</strong>” / “<strong>Fleece</strong>” for AGM.<br/><br/><strong>Line 3:</strong><br/><br/><strong>3</strong> – Click “<strong>Select</strong>,” then click “<strong>19 – CAN Gateway</strong>.”<br/><br/><strong>4</strong> – Click “<strong>Adaptation – 10</strong>.”<br/><br/><strong>5</strong> – At the very top of this page, there is a drop-down menu.<br/>From this drop-down menu, select “<strong>Battery Adaptation—Battery Manufacturer</strong>.”<br/><br/><strong>6</strong> – On this same page, there is a second drop-down menu further down the page<br/>.<br/>From this menu, select the corresponding brand:<br/>For example: For the VARTA E39, select “<strong>VAO</strong>.”<br/><br/><strong>Line 4:</strong><br/><br/><strong>3</strong> – Click “<strong>Select</strong>,” then click “<strong>19 – CAN Gateway</strong>.”<br/><br/><strong>4</strong> – Click “<strong>Adaptation – 10</strong>.”<br/><br/><strong>5</strong> – At the very top of this page, there is a drop-down menu.<br/>From this drop-down menu, select “<strong>Battery Configuration—Battery Serial Number</strong>.”<br/><br/><strong>6</strong> – On this same page, there is a second drop-down menu toward the bottom<br/>.<br/>In this menu, enter the corresponding serial number:<br/>Note: Enter only the <strong>last 10 digits</strong> of the serial number.<br/><br/><strong>Line 5 (AGM battery option):</strong></p>\n<p><br/><strong>3</strong> – Click “<strong>Select</strong>,” then click “<strong>19 – CAN Gateway</strong>.”<br/><br/><strong>4</strong> – Cliquer sur “<strong>Codage – 07</strong>” puis cliquer “<strong>Assistant Codage Long</strong>“<br/><br/><strong>5</strong> – Select the octet “<strong>3</strong>,” then the byte “<strong>3</strong>“<br/><br/><strong>6</strong> – Finally, change the value of bits 4–7 to “<strong>30—Battery Architecture/Type: Absorbent Glass Matt (AGM)</strong>,” then confirm.</p>\n<hr/>\n<p><strong>Battery Status Detection Functions:</strong><br/>Battery status detection in the battery data module calculates the following parameters, which are transmitted via the LIN bus to the J533 data bus diagnostic interface:<br/>1 “No battery” detection: If the battery data module does not detect a battery for more than 30 seconds at<br/>, a corresponding bit is set to 1<br/>2 Voltage currently allowing optimal battery charging<br/>3 “Engine Start Readiness” bit. It indicates whether the battery is currently capable of starting<br/>the engine or not<br/>4. The amount of charge that can still be temporarily drawn from the battery before reaching the limit of<br/>engine starting capability<br/>5. Current state of charge of the battery<br/>6. Battery aging. Battery aging can be determined using parameters such as<br/>the battery’s energy storage capacity and instantaneous power.<br/>7 battery open-circuit voltage<br/>8 battery internal resistance  </p>\n<p><strong>The battery sensor in the J367 battery monitoring control unit:</strong></p>\n<p>Knowing whether the battery has enough electrical energy to restart the engine is essential for the start-stop system to function properly.<br/>The control module is located directly on the “negative” terminal of the ground wire and is connected to the diagnostic interface via the LIN data bus.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/charge-batterie-c76863ff.webp\"/></figure>\n<p><strong>Signal Usage:</strong><br/>The battery sensor records the following values:<br/>– Battery temperature<br/>– Battery voltage<br/>– Charging current<br/>The battery temperature is calculated using a lookup table and the ambient temperature.<br/>It also allows for estimates of the battery’s charging time.<br/>Using the data obtained in this way, it is possible to adjust the charging control—particularly the charging voltage—to the battery’s state of charge and operating conditions. The goal is to increase the availability of the start-stop system by optimally utilizing data from the starter battery. </p>\n<p><strong>Consequences in the Event of a Malfunction</strong><br/>If the battery sensor is defective, the battery status can no longer be detected correctly.<br/>A fault is logged in the diagnostic interface’s fault memory. The start-stop system is deactivated. </p>\n<p><strong>Battery</strong></p>\n<p>The vehicle’s battery is housed in the engine compartment and protected by a battery tray. The size and type of battery depend on the engine version, equipment, and country-specific variant. Standard batteries, EFB batteries, and AGM batteries are used.<br/>Vehicles with gasoline engines and start/stop systems are equipped with an EFB battery, while vehicles with diesel engines and start/stop systems are equipped with an AGM battery. Vehicles with auxiliary heaters typically have an AGM battery.   </p>\n<p><strong>EFB</strong></p>\n<p>An EFB battery (short for Enhanced Flooded Battery) is a reinforced flooded battery. The positive plate inside the battery is coated with an additional layer of polyester mesh. This provides the battery’s active material with additional support on the plate. These batteries have greater resistance to charge-discharge cycles than standard batteries. During charging, an EFB battery is treated like a standard battery.    </p>\n<p><strong>AGM Battery</strong></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/batterie-agm-f4b81a74.webp\"/></figure>\n<p>In AGM (Absorbent Glass Mat) batteries, the battery electrolyte is retained within a microporous glass mat. An AGM battery is characterized not only by even greater resistance to charge-discharge cycles compared to an EFB battery, but also by its leak-proof design. When charging, follow the charger’s user manual and, if applicable, select the AGM battery program.  </p>\n<p>In the case of AGM batteries, the automotive battery electrolyte is retained within a microporous glass mat. In addition to<br/>increased resistance to charge-discharge cycles, an AGM battery is characterized by its high level of leak resistance. Sealing is of crucial<br/>importance, particularly when the battery is installed in<br/>the passenger compartment. When charging, follow the charger’s user manual and, if necessary, select the program for<br/>AGM batteries.   </p>\n<p>Below, we can see the brand, serial number, and manufacturer of the battery</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/batterie-124711ff.webp\"/></figure>","tarraco-kn-speed-of-radar-deactivation-or-reversing-camera":"<p><strong>Purpose:</strong> Selects the speed at which the radar or reversing camera is deactivated.  <br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click “<strong>Select</strong>,” then click “<strong>10 – Parking Assistance</strong>.”<br/><br/><strong>4</strong> – Click “<strong>Security Access – 16</strong>,” then enter the code “<strong>71679</strong>“<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Switch-off speed for parking assist</strong>“.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, choose a value between<strong>“0</strong>” and<strong>“15</strong>” km/h, depending on your preference.</p>","tarraco-kn-speed-threshold-settings-for-cornering-light-activation":"<p><strong>Purpose:</strong> Allows you to adjust the speed thresholds for turning the corner lights on and off via the fog lights. (Corner Lights)   <br/><br/><strong>Warning! There are 2 lines of coding to do here. </strong> </p>\n<p><br/><strong>Proceed :</strong> <br/><strong>1 </strong>– Engine off, ignition off, connect your official VAG-COM VCDS cable to<br/>the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2 </strong>– Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1 (Turn Signal Activation Speed):</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – At the very top of this page, there is a drop-down menu.<br/>From this drop-down menu, select <strong>“statisches Kurvenlicht-Untere Geschwindigkeitsschwelle.”</strong><br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu located toward the bottom<br/>.<br/>In this menu, adjust the value accordingly and then confirm. (Default value: 0 km/h) </p>\n<p><em>Note: When this value is specified, the turn signals are turned off when the vehicle is stationary and are activated only once the corresponding set speed is reached.</em> <br/><br/><strong>Line 2 (Turn Signal Fade-Out Speed):</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on “<strong>Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – At the very top of this page, there is a drop-down menu.<br/>From this drop-down menu, select <strong>“statisches Kurvenlicht-Obere Geschwindigkeitsschwelle.”</strong><br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu located toward the bottom<br/>.<br/>In this menu, adjust the value as needed and then confirm. (Default value: 32 km/h) </p>\n<p><em>Note: This is probably a good idea up to a maximum speed of 60 km/h (in urban areas), because otherwise the cornering lights will also be activated on country roads if the steering angle is sufficient.  </em></p>","tarraco-kn-start-stop-deactivation":"<p><strong>Purpose:</strong> to disable Start and Stop completely.  <br/></p>\n<p><strong>Watch out! There are 1 or 2 lines of coding to do here, depending on the method.</strong> <em>(After 2019 deactivation no longer works according to gateway reference “AA”)  </em><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostic socket or OBDeleven box.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program or the OBDeleven application.<br/><br/><br/><strong>Method 1 (Voltage method):</strong></p>\n<p><strong>VCDS :  </strong><br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“19 – CAN Gateway</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>5</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose <strong>“Limite de tension de départ marche/arrêt” / “Start/Stop voltage limit”</strong>.<br/><br/><strong>6</strong> – On this same page, there is a second drop-down menu, but at the bottom<br/>of the page.<br/>On this menu, select<strong>“12</strong>” (default value = <strong>7.6V</strong>) then validate.<br/></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/vw_start_stop_change_voltage_limit_value-a50bc29b.webp\"/></figure>\n<p><strong><strong>OBDeleven:</strong></strong></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/obdelevenstartstoptension-ec0170bc.webp\"/></figure>\n<p><strong>YouTube video:</strong></p>\n<figure>\n</figure>\n<hr/>\n<p><strong>Method 2 (Temperature method):</strong></p>\n<p><strong>VCDS :</strong> </p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“19 – CAN Gateway</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Adaptation – 10</strong>”.</p>\n<p><strong>5</strong> – On this page, at the top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Start/Stopp Auntemperaturvorgabe-Minimaltemperatur</strong>”.</p>\n<p><strong>6</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>Select<strong>“50</strong>” (default value = <strong>-50.0</strong>) and confirm.</p>\n<p><strong>Line 2:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“19 – CAN Gateway</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Adaptation – 10</strong>”.</p>\n<p><strong>5</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Start/Stopp Auntemperaturvorgabe-Maximaltemperatur</strong>”.</p>\n<p><strong>6</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>Select<strong>“50</strong>” (default value = <strong>-50.0</strong>) and confirm.</p>\n<p><strong>OBDeleven:</strong></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/obdelevenstarstoptemp-494422ad.webp\"/></figure>","tarraco-kn-suppress-electric-tailgate-beeps":"<p><strong>Purpose</strong>: to deactivate beeps when opening/closing the trunk/electric liftgate.  </p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on “<strong>Select”</strong>, then click on “Select”.<strong>  6D – Elect. Trunk” </strong>.</p>\n<p><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then type in the code<strong>“12345</strong>”<br/><br/> 5 – Click on<strong>“Adaptation – 10</strong>”.<br/><br/> 6 – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“ENG131232-MAS01911 – Ausstattungen aktivieren-Tongeber</strong>” /<strong>“activate equipment sound generator</strong>”.</p>\n<p><strong>7</strong> – On this same page, there is a second drop-down menu, at the bottom<br/>of the page.<br/>On this menu, select<strong>“not</strong> <strong>active</strong>” and confirm.<br/></p>","tarraco-kn-third-brake-light-on-when-trunk-is-open":"<p><strong>Purpose:</strong> to keep the 3rd brake light on if the trunk is not fully closed. For security lighting at night or to make sure your safe is securely closed.  <br/><br/><br/><strong>Warning! There are 2 lines of coding to do here. </strong> <br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Leuchte22BR MA57-Lichtfunktion C 22</strong>”.<br/><br/><strong>7</strong> – On this same page, there’s a second drop-down menu at the bottom<br/>of the page.<br/>On this, select the value<strong>“Heckdeckel Offen</strong>” and confirm. <em>(Origin: nicht aktiv)</em><br/><br/><br/><strong>Line 2:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Leuchte22BR MA57-Dimmwert CD 22</strong>”.<br/><br/><strong>7</strong> – On the same page, you’ll find a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, choose a value between<strong>“0</strong>” and<strong>“100</strong>” depending on the power of the brake light, then confirm. <em>(Origin: 0)</em></p>","tarraco-kn-trailer-assist-activation":"<p><strong>Purpose:</strong> to activate Trailer Assist, which takes control of steering when the trailer is attached. Trailer direction is determined by the mirror adjustment knob.   </p>\n<p>Note:  </p>\n<ul>\n<li>Suitable only for vehicles with PR no. 7X5, KA6 and 1M6.</li>\n<li>The camera must be replaced for vehicles equipped with KA1 and KA2 cameras.</li>\n</ul>\n<p><br/><br/><strong>Warning! There are 7 lines of coding to do here. </strong> <br/><br/><strong>Proceed :</strong> <br/><strong>1 </strong>– Engine off, ignition off, connect your official VAG-COM VCDS cable to<br/>the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2 </strong>– Switch on the ignition and run the VCDS program.<br/><br/><br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“5F – Electr. information</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6-</strong> On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Car_Function_List_BAP_Gen2 Trailer_Assistant_msg_bus_0x36</strong>”.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu, but at the bottom<br/>of the page.<br/>On this menu, select<strong>“terminal 15</strong>” and confirm.</p>\n<p><strong>Line 2:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“5F – Electr. information</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6-</strong> On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Car_Function_List_BAP_Gen2 Trailer_Assistant_0x36</strong>”.<br/><br/><strong>7</strong> – On the same page, there’s a second drop-down menu at the bottom<br/>of the page.<br/>Select<strong>“Activated</strong>” and confirm.<br/><br/><strong>Line 3:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“5F – Electr. information</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Car_Function_Adaptations_Gen2 menu_display_trailer_assistant_over_threshold_high</strong>”.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu, but at the bottom<br/>of the page.<br/>On this menu, choose<strong>“activated</strong>” and confirm.<br/><br/><strong>Line 4:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“5F – Electr. information</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Car_Function_Adaptations_Gen2 menu_display_trailer_assistant_after_disclaimer</strong>”.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu, but at the bottom<br/>of the page.<br/>On this menu, choose<strong>“activated</strong>” and confirm.</p>\n<p><strong>Line 5:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“17 – Instruments</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>”.<br/><br/><strong>5</strong> – Select byte<strong>“12</strong>”<br/>Then check Bit<strong>“5</strong>”:<strong>“Trailer Assist</strong>”.<br/><br/><strong>Line 6:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“6C – <strong>Rear camera system</strong></strong>”.<br/><br/><strong>4</strong> – Click on “<strong>Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>”.<br/><br/><strong>5</strong> – Select byte<strong>“10</strong>”<br/>Then check Bit<strong>“3</strong>”:<strong>“ARA optical</strong>”.</p>\n<p><strong>Line 7:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“10 – Assistance Stationt/Park</strong><strong>Assist</strong>”.<br/><br/><strong>4</strong> – Click on “<strong>Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>”.<br/><br/><strong>5</strong> – Select byte<strong>“0</strong>”<br/>Then check Bit<strong>“3</strong>”:<strong>“Trailer Assist</strong>”.<br/></p>\n<ul><li><figure><img decoding=\"async\" loading=\"lazy\" src=\"img/trailer-assist-1-1024x682-efc12928.webp\"/></figure></li><li><figure><img decoding=\"async\" loading=\"lazy\" src=\"img/trailer-assist-2-1024x682-6679ec7d.webp\"/></figure></li></ul><a></a><a></a><a></a>","tarraco-kn-activate-fog-lamps-with-daytime-running-lights-drl":"<p><strong>Purpose:</strong> Enables the daytime running lights (DRL) to turn on along with the fog lights.  <br/><br/><br/><strong>Warning! There are 2 lines of coding to do here. </strong> <br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – At the very top of this page, there is a drop-down menu.<br/>From this drop-down menu, select “<strong>Leuchte12NL LB45-Lichtfunktion B 12</strong>“<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu located toward the bottom<br/>of the page.<br/>From this menu, select “<strong>Daytime running lights</strong>” and then confirm.<br/></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/5Q0-937-084-Q_Module09_Adaptation_drl_with_fog_lig-cbaa08b2.webp\"/></figure>\n<p><strong>Line 2:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.</p>\n<p><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.</p>\n<p><strong>6</strong> – At the very top of this page, there is a drop-down menu.<br/>From this drop-down menu, select “<strong>Leuchte13NL RB5-Lichtfunktion B 13</strong>“</p>\n<p><strong>7</strong> – On this same page, there is a second drop-down menu located toward the bottom<br/>of the page.<br/>From this menu, select “<strong>Daytime running lights</strong>” and then confirm.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/5Q0-937-084-Q_Module09_Adaptation_drl_with_fog_lig-f4968343.webp\"/></figure>","tarraco-kn-vehicle-hold-assist":"<p><strong>Purpose:</strong> To set the memory of the Auto Hold button (A) – the Auto Hold function can be set to be always active when the car is started, never active or held at the last setting before the ignition is switched off.  </p>\n<p>The vehicle must be equipped with the Auto Hold function.  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click “<strong>Select</strong>,” then click “<strong>03 – ABS Brakes</strong>.”<br/><br/><strong>4</strong> – Click “<strong>Adaptation – 10</strong>.”<br/><br/><strong>5</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“AUTO HOLD functional status</strong>”.<br/><br/><strong>6 – </strong> On this same page, there is a second drop-down menu located toward the bottom<br/>.<br/>From this menu, select the value based on your preference:</p>\n<ul>\n<li>“<strong>Last setting</strong>” (remembers state before engine cut-off)</li>\n<li>“<strong>Never active</strong>” (deactivated at every startup)</li>\n<li>“<strong>Always active</strong>” (activated at every startup)</li>\n</ul>\n<p>then click “Submit.”</p>"};
